package com.projexa.coaching.portal.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import com.projexa.coaching.common.security.ResourceAccess; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/portal") public class PortalController {private final JdbcTemplate db; private final ResourceAccess access; public PortalController(JdbcTemplate db, ResourceAccess access){this.db=db; this.access=access;}
@GetMapping("/student/{studentId}") @PreAuthorize("hasAnyRole('STUDENT','PARENT','TEACHER','INSTITUTE_OWNER','INSTITUTE_ADMIN')") public Map<String,Object> student(@PathVariable UUID studentId, Authentication auth){UUID t=TenantContextHolder.getRequired(); access.requireOwnStudent(t, studentId, auth);Map<String,Object> s=db.queryForMap("select id,admission_number,first_name,last_name,status from students where id=? and tenant_id=?",studentId,t);List<Map<String,Object>> attendance=db.queryForList("select ar.status,count(*) total from attendance_records ar where ar.student_id=? and ar.tenant_id=? group by ar.status",studentId,t);List<Map<String,Object>> fees=db.queryForList("select invoice_number,amount,paid_amount,due_date,status from invoices where student_id=? and tenant_id=? order by due_date",studentId,t);List<Map<String,Object>> results=db.queryForList("select r.* ,e.name exam_name from results r join exams e on e.id=r.exam_id where r.student_id=? and r.tenant_id=? and r.status='PUBLISHED' order by r.published_at desc",studentId,t);return Map.of("student",s,"attendance",attendance,"fees",fees,"results",results);}
}
